window.RP_SESSION={"id":"S-6bf6c2417eb8","messages":[{"id":"RP-III-0182365","time":"2026-09-18T22:44:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"··· 가끔 좋지 않은 꿈을 꿀 때가 많습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0182366","time":"2026-09-18T22:44:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!독백","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0182367","time":"2026-09-18T22:44:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"조용히, 피어오르는\n또 다른 누군가의 이야기.\n\n※해당 RP는 중참이 불가합니다.\n※중참 희망시 해당 기입자께 문의 바랍니다.","characters":[]},{"id":"RP-III-0182368","time":"2026-09-18T22:45:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"때로는 그것이 꿈인지 아닌지 구별이 가지 않아, 제 옆에 존재하는 션을 몇 십분 동안 껴안고 있을 때도 있었고요.\n\n그러나···. 꿈의 반복이 일어나지 않았기에 마리우스는 의심하지 않은 걸지도 모릅니다.\n\n지금은, 그 반대고요.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0182369","time":"2026-09-18T22:46:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"반복되는 내용의 꿈.\n\n꼭 ‘그 때’ 처럼 불길한 기운이 감도는 구역들.\n\n마리우스는 고민했습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0182370","time":"2026-09-18T22:46:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"또 혼자 향할까?\n\n남에게 피해를 끼치는 것이 아닐까?\n\n길드에게 도움이 되지 않는 짓이지 않을까?\n\n내가 지금 이렇게, 사람들을 불러도 괜찮은 것일까?","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0182371","time":"2026-09-18T22:47:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그제서야, 마리우스의 시선이 달빛에 일렁이던 펜던트로 향합니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0182372","time":"2026-09-18T22:47:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"······.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0182373","time":"2026-09-18T22:47:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"아니요, 이런 질문들에는 의미가 없습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0182374","time":"2026-09-18T22:48:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"어설픈 용맹은, 설령 그것이 마리우스 본인이 정의한 것이라도,","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0182375","time":"2026-09-18T22:49:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"절대 자신이 도움을 요청한다 해서 무너질 이유가 없다는 걸···. 이제는 알았으니까요.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0182376","time":"2026-09-18T22:49:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"굳게 마음을 다잡고서, 빛바랜 검은 눈이 다시금 펜던트로 향합니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0182377","time":"2026-09-18T22:49:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"······.\n\n도와주세요.\n\n마리우스는 한마디를 내뱉습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0182378","time":"2026-09-18T22:49:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0182379","time":"2026-09-18T22:49:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]},{"id":"RP-III-0182380","time":"2026-09-19T00:02:00+09:00","room":"RP III","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"unresolved","type":"dialogue","body":"!독백","characters":[]},{"id":"RP-III-0182381","time":"2026-09-19T00:02:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"조용히, 피어오르는\n또 다른 누군가의 이야기.\n\n※해당 RP는 중참이 불가합니다.\n※중참 희망시 해당 기입자께 문의 바랍니다.","characters":[]}]};
